create schema if not exists kitchen;
revoke all on schema kitchen from public;
create table kitchen.owner(id smallint primary key default 1 check(id=1),email text not null unique,password_hash text not null,preferences jsonb not null default '{}',created_at timestamptz not null default now());
create table kitchen.sessions(token_hash text primary key,owner_id smallint not null references kitchen.owner(id),expires_at timestamptz not null,created_at timestamptz not null default now());
create index sessions_expiry on kitchen.sessions(expires_at);
create table kitchen.media(id uuid primary key,owner_id smallint not null default 1 references kitchen.owner(id),object_key text not null unique,digest text not null,mime text not null,bytes bigint not null,kind text not null,origin text not null check(origin in ('source','personal','ai')),state text not null default 'queued',caption text not null default '',derivatives jsonb not null default '{}',metadata jsonb not null default '{}',parent_id uuid references kitchen.media(id),created_at timestamptz not null default now(),unique(digest,origin));
create table kitchen.categories(id uuid primary key,parent_id uuid references kitchen.categories(id),name text not null,normalized_name text not null,aliases text[] not null default '{}',media_id uuid references kitchen.media(id),image_state text not null default 'pending',image_revision integer not null default 1,manual_image boolean not null default false,created_at timestamptz not null default now(),check(parent_id is distinct from id));
create unique index category_sibling_unique on kitchen.categories(coalesce(parent_id,'00000000-0000-0000-0000-000000000000'),normalized_name);
create table kitchen.recipes(id uuid primary key,owner_id smallint not null default 1 references kitchen.owner(id),revision integer not null default 1,status text not null check(status in('draft','published','trash')),title text not null,content jsonb not null,favorite boolean not null default false,primary_media_id uuid references kitchen.media(id),search_text text not null default '',active_minutes numeric,total_minutes numeric,classification text not null default 'לא ידוע',difficulty text not null default 'לא ידוע',tags text[] not null default '{}',cook_count integer not null default 0,last_cooked_at timestamptz,rating numeric check(rating between 1 and 5),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create index recipes_recent on kitchen.recipes(status,updated_at desc,id);
create index recipes_title on kitchen.recipes(title);
create index recipes_tags on kitchen.recipes using gin(tags);
create index recipes_search on kitchen.recipes using gin(to_tsvector('simple',search_text));
create table kitchen.recipe_versions(id uuid primary key,recipe_id uuid not null references kitchen.recipes(id),revision integer not null,content jsonb not null,reason text not null,created_at timestamptz not null default now(),unique(recipe_id,revision));
create table kitchen.recipe_categories(recipe_id uuid not null references kitchen.recipes(id),category_id uuid not null references kitchen.categories(id),approved_at timestamptz not null default now(),primary key(recipe_id,category_id));
create table kitchen.ingredients(id text not null,recipe_id uuid not null references kitchen.recipes(id),position integer not null,group_name text not null,name text not null,unit text not null,amount jsonb not null,original text not null,details jsonb not null,primary key(recipe_id,id));
create index ingredient_names on kitchen.ingredients(name,recipe_id);
create table kitchen.steps(id text not null,recipe_id uuid not null references kitchen.recipes(id),position integer not null,group_name text not null,text text not null,details jsonb not null,primary key(recipe_id,id));
create table kitchen.recipe_media(recipe_id uuid not null references kitchen.recipes(id),media_id uuid not null references kitchen.media(id),position integer not null default 0,primary key(recipe_id,media_id));
create table kitchen.import_items(id uuid primary key,status text not null default 'queued',revision integer not null default 1,draft jsonb,previous_draft jsonb,suggestions jsonb,error text,recipe_id uuid references kitchen.recipes(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table kitchen.import_media(item_id uuid not null references kitchen.import_items(id),media_id uuid not null references kitchen.media(id),position integer not null,primary key(item_id,media_id));
create table kitchen.jobs(id uuid primary key,type text not null,operation text not null,dedup_key text not null unique,payload jsonb not null,status text not null default 'queued',attempts integer not null default 0,max_attempts integer not null default 3,run_after timestamptz not null default now(),lease_until timestamptz,lease_token uuid,dispatched boolean not null default false,result jsonb,error text,provider_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index jobs_claim on kitchen.jobs(status,run_after,created_at);
create table kitchen.ai_usage(id uuid primary key,job_id uuid not null references kitchen.jobs(id),operation text not null,model text not null,prompt_version text not null,schema_version text not null,status text not null,usage jsonb,estimated_usd numeric,pricing_date date,duration_ms integer,provider_id text,created_at timestamptz not null default now());
create index ai_daily on kitchen.ai_usage(created_at,status);
create table kitchen.cooking(id uuid primary key,recipe_id uuid not null references kitchen.recipes(id),recipe_revision integer not null,snapshot jsonb not null,target text not null,state text not null default 'active',checked_ingredients text[] not null default '{}',checked_steps text[] not null default '{}',step_index integer not null default 0,revision integer not null default 1,rating integer check(rating between 1 and 5),notes text not null default '',created_at timestamptz not null default now(),finished_at timestamptz);
create index cooking_active on kitchen.cooking(state,created_at desc);
create table kitchen.timers(id uuid primary key,cooking_id uuid not null references kitchen.cooking(id),name text not null,duration_seconds integer not null check(duration_seconds>0),remaining_seconds integer not null,ends_at timestamptz,state text not null default 'paused');
create table kitchen.meals(id uuid primary key,name text not null,scheduled_at timestamptz,adults integer not null,children integer not null,style text not null,revision integer not null default 1,notes text not null default '',outcome text,created_at timestamptz not null default now());
create table kitchen.meal_items(id uuid primary key,meal_id uuid not null references kitchen.meals(id),recipe_id uuid not null references kitchen.recipes(id),recipe_revision integer not null,snapshot jsonb not null,target text not null,position integer not null);
create table kitchen.preparation(id uuid primary key,meal_id uuid not null references kitchen.meals(id),revision integer not null default 1,plan jsonb not null,checked text[] not null default '{}',created_at timestamptz not null default now());
create table kitchen.shopping_lists(id uuid primary key,meal_id uuid references kitchen.meals(id),name text not null,revision integer not null default 1,created_at timestamptz not null default now());
create table kitchen.shopping_items(id uuid primary key,list_id uuid not null references kitchen.shopping_lists(id),name text not null,unit text not null,amount jsonb not null,source_refs jsonb not null,department text not null default 'כללי',state text not null default 'needed',manual boolean not null default false,edited boolean not null default false,position integer not null default 0);
create table kitchen.pantry(id uuid primary key,name text not null,normalized_name text not null unique,amount jsonb,unit text,staple boolean not null default false,use_soon boolean not null default false);
create table kitchen.experiences(id uuid primary key,cooking_id uuid not null unique references kitchen.cooking(id),recipe_id uuid not null references kitchen.recipes(id),recipe_revision integer not null,target text not null,rating integer,notes text not null,created_at timestamptz not null default now());
create table kitchen.experience_media(experience_id uuid not null references kitchen.experiences(id),media_id uuid not null references kitchen.media(id),primary key(experience_id,media_id));
create table kitchen.assistant_messages(id uuid primary key,job_id uuid not null references kitchen.jobs(id),recipe_id uuid references kitchen.recipes(id),cooking_id uuid references kitchen.cooking(id),question text not null,answer jsonb,created_at timestamptz not null default now());
